import { register } from 'tsx/esm/api'

// The dsh source launch registers tsx with the base tsconfig explicitly:
// tsx does not follow tsconfig `extends` when resolving `paths`, so without
// this the @deepseek-ai/* aliases (vendor sources) never resolve. A shell
// env prefix (TSX_TSCONFIG_PATH=...) would work but breaks on Windows.
register({ tsconfig: 'tsconfig.base.json' })
